import unittest,re
from tools.kjv_archive import load_register,read
class ZephaniahGatheringTests(unittest.TestCase):
 def test_civic_boast_and_gathered_people(self):
  prior,_=load_register('0.10-kjv.181');lang,manifest=load_register('0.10-kjv.182')
  self.assertEqual(prior.lexicon,{k:lang.lexicon[k] for k in prior.lexicon})
  for attr in ('pairs','suffix','prefix','possessors','roman'):self.assertEqual(getattr(prior,attr),getattr(lang,attr))
  cases={c['id'].removeprefix('zephaniah-'):c for c in read(lang.folder/'zephaniah-civic-boast-and-gathered-people-cases.json')};self.assertEqual(len(cases),53)
  for c in cases.values():
   r=lang.compile(c['analysis']);self.assertEqual(c['expectedText'],r['text']);self.assertEqual(c['expectedGloss'],r['gloss']);self.assertNotIn('!',r['text'])
   self.assertFalse({'one','matter','worship','care'}&set(r['keys']))
  anchors={'1:1': ['kjv_zephaniah_prophet son of kjv_cushi_zephaniah', 'son of kjv_gedaliah_cushi', 'son of kjv_amariah_gedaliah', 'son of kjv_hizkiah_zephaniah', 'kjv_josiah_amon son of kjv_amon_manasseh'], '1:2': ['ipl all thing:pl', 'from off land entirely consume'], '1:3': ['man and beast', 'bird:pl of heaven', 'kjv_fish:pl of sea', 'kjv_stumblingblock:pl with wicked', 'ipl man from off land'], '1:4': ['mypl/hand', 'all inhabit:ag:pl', 'kjv_baal_deity', 'name of kjv_chemarims with priest:pl'], '1:5': ['army of heaven upon house:pl top:pl', 'by kjv_lord swear', 'by kjv_malcham_cult swear'], '1:6': ['back from kjv_lord', 'seek:neg:perf', 'nor for he ask:perf'], '1:7': ['thy/peace hold', 'kjv_sacrifice prepare', 'his/guest:pl call'], '1:8': ['kjv_sacrifice of kjv_lord', 'prince:pl and child:pl of king', 'strange clothing'], '1:9': ['on kjv_threshold leap', 'house:pl of their/master:pl', 'kjv_violence and deceit'], '1:10': ['kjv_fish gate', 'from two:ord', 'great break:ev noise from hill:pl'], '1:11': ['kjv_maktesh', 'kjv_merchant people', 'silver carry'], '1:12': ['ipl kjv_jerusalem with candle:pl', 'their/kjv_wine_lees', 'kjv_lord good do:neg:fu neither he evil do:fu'], '1:13': ['their/kjv_goods spoil', 'build:fu but they:a inhabit:neg', 'kjv_vineyard:pl plant', 'wine of it drink:neg'], '1:14': ['near be:pr it near be:pr', 'voice of day', 'bitter:adv cry'], '1:15': ['day of wrath', 'kjv_trouble and distress', 'destroy:ev and kjv_desolate:ev', 'darkness and dim:ev', 'cloud:pl and thick darkness'], '1:16': ['trumpet and alarm', 'fortify:psv:adj city:pl', 'high kjv_tower:pl'], '1:17': ['ipl distress', 'like blind man:pl', 'against kjv_lord sin', 'blood as dust', 'flesh as kjv_dung'], '1:18': ['neither their/silver nor their/gold', 'whole land', 'fire of his/jealous:ev', 'swift remove:ev'], '2:1': ['yourselves together gather', 'yes together gather', 'desire:psv:neg:adj nation'], '2:2': ['before decree forth bring', 'day as kjv_chaff', 'fierce anger', 'day of anger'], '2:3': ['all you kjv_meek_disposition', 'his/judgment work:perf', 'kjv_righteousness seek', 'perhaps you', 'hide:psv:fu'], '2:4': ['kjv_gaza', 'kjv_ashkelon', 'kjv_ashdod at noon', 'kjv_ekron up root'], '2:5': ['kjv_cherethite:pl be:excl', 'kjv_canaan_land', 'kjv_philistine:pl', 'ipl even thou:a destroy', 'no inhabit:ag'], '2:6': ['small house:pl for shepherd:pl', 'sheepfold:pl for flock:pl'], '2:7': ['remainder of house of kjv_judah', 'kjv_ashkelon', 'evening down lie', 'kjv_captivity away turn'], '2:8': ['ipl kjv_reproach of kjv_moab', 'rail:ev:pl', 'mypl/people kjv_reproach:caus', 'their/boundary'], '2:9': ['as ipl live', 'kjv_sodom', 'kjv_gomorrah', 'kjv_nettle:pl', 'salt kjv_pit:pl', 'mypl/people they:a spoil', 'mypl/people they:a possess'], '2:10': ['their/pride', 'people of kjv_lord', 'kjv_reproach:caus', 'themselves great'], '2:11': ['all god:pl of earth starve:caus', 'every person from his/place', 'kjv_isle:pl of kjv_heathen'], '2:12': ['kjv_ethiopian:pl', 'mypl/sword slay:psv'], '2:13': ['his/hand against kjv_north', 'kjv_assyria destroy', 'kjv_nineveh', 'dry like kjv_wilderness'], '2:14': ['beast:pl of nation:pl', 'both kjv_cormorant and kjv_bittern', 'higher kjv_lintel:pl', 'their/voice', 'kjv_threshold:pl', 'kjv_cedar work'], '2:15': ['without worry', 'her/heart', 'ipl be:pr and none except ipl', 'be:excl', 'every person', 'his/hand shake'], '3:1': ['woe to she', 'kjv_pollute_sacred', 'oppress:cv city be:excl'], '3:2': ['voice obey:neg', 'kjv_chasten:ev receive:neg', 'kjv_lord trust:neg', 'her/god draw:neg'], '3:3': ['her/prince:pl', 'roar:cv lion:pl', 'evening wolf:pl', 'bone:pl until tomorrow kjv_chew:neg'], '3:4': ['levity:adj and faithless', 'kjv_sanctuary kjv_pollute_sacred', 'to law kjv_violence'], '3:5': ['kjv_righteous kjv_lord', 'kjv_iniquity do:neg', 'every morning', 'his/judgment to light', 'unjust no shame'], '3:6': ['ipl nation:pl off cut', 'their/street:pl kjv_desolate', 'none by pass', 'no man', 'no inhabit:ag'], '3:7': ['ipl say:pa', 'thou ipl:a fear', 'their/dwell:ev', 'however ipl they:a punish', 'early rise', 'all their/do:ev:pl corrupt'], '3:8': ['until day that ipl to prey up rise', 'mypl/purpose', 'kingdom:pl assemble', 'mypl/indignation', 'all earth', 'mypl/jealous:ev'], '3:9': ['ipl to people pure language turn', 'they all', 'with one_num consent'], '3:10': ['beyond river:pl of kjv_ethiopia', 'mypl/suppliant:pl', 'daughter of mypl/disperse:psv:adj', 'mypl/kjv_offering'], '3:11': ['all thy/do:ev:pl', 'against ipl transgress', 'shame:psv:neg', 'thy/pride', 'mypl/holy mountain'], '3:12': ['kjv_afflict:psv:adj and poor people', 'name of kjv_lord trust'], '3:13': ['kjv_iniquity do:neg', 'nor false word:pl', 'deceit:adj tongue', 'their/mouth', 'feed:fu and down lie', 'none they:a afraid'], '3:14': ['daughter of kjv_zion', 'oh kjv_israel', 'all heart', 'daughter of kjv_jerusalem'], '3:15': ['thy/judgment:pl', 'thy/enemy', 'king of kjv_israel even kjv_lord', 'no more evil see'], '3:16': ['kjv_jerusalem', 'fear:neg:imp', 'kjv_zion', 'thy/hand:pl kjv_slack be:neg:opt'], '3:17': ['he save:fu', 'with joy rejoice', 'in his/love rest', 'with sing:ev joy'], '3:18': ['solemn kjv_assembly', 'who of thou', 'kjv_reproach of it burden'], '3:19': ['all that thou:a kjv_afflict', 'she that kjv_limp', 'she that out drive', 'praise and fame', 'every land where they shame'], '3:20': ['ipl you:a again bring', 'time that ipl you:a gather', 'name and praise', 'your/kjv_captivity before your/eye:pl']}
  for ref,parts in anchors.items():
   for part in parts:self.assertIn(part,cases[ref.replace(':','-')]['analysis'])
  self.assertIn('perhaps you',cases['2-3']['analysis'])
  self.assertIn('ipl be:pr and none except ipl',cases['2-15']['analysis'])
  self.assertIn('with one_num consent',cases['3-9']['analysis'])
  self.assertIn('he in his/love rest:fu',cases['3-17']['analysis'])
  self.assertFalse(any(':du' in c['analysis'] or 'wesg' in c['analysis'] for c in cases.values()))
  self.assertEqual(len(set(lang.lexicon)-set(prior.lexicon)),8)
  self.assertEqual(manifest['baseForgeHead'],read(prior.folder/'manifest.json')['forgeHead'])
